        props=s.get('properties',{})
        if s.get('additionalProperties') is False:assert set(x)<=set(props),path
        for k,v in x.items():
            if k in props:validate(v,props[k],path+'.'+k)
    if isinstance(x,list) and 'items' in s:
        for v in x:validate(v,s['items'],path+'[]')
